const state={scenario:'studio',count:4,model:'Sharmax Atlas 1000 LX',generating:false,referenceFiles:[],remoteReferences:[],sourceFilter:'all',searchEngine:'both',searching:false};
const $=(s,r=document)=>r.querySelector(s);const $$=(s,r=document)=>[...r.querySelectorAll(s)];
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),3300)}
function esc(value){return String(value||'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]))}
function updateSummary(){const labels={studio:'каталог на белом фоне',details:'крупные узлы техники',nature:'техника в природе'};$('#generateSummary').textContent=state.count+' кадра · '+labels[state.scenario]}
function updateReferenceCount(){const total=state.referenceFiles.length+state.remoteReferences.length;$('#referenceCount').textContent=total?'Выбрано референсов: '+total+' · будут учтены при генерации':'Для точной модели добавь 1–4 исходных фото'}
function selectedAngles(){return $$('.angle-toggle input:checked').map(input=>input.dataset.angle)}
async function compactReference(file){const url=URL.createObjectURL(file);const image=new Image();await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=reject;image.src=url});const ratio=Math.min(1,1600/Math.max(image.naturalWidth,image.naturalHeight));const canvas=document.createElement('canvas');canvas.width=Math.round(image.naturalWidth*ratio);canvas.height=Math.round(image.naturalHeight*ratio);canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);URL.revokeObjectURL(url);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.9));return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob)})}
function angleLabel(angle){return {'front-left':'Передний левый',side:'Профиль','rear-right':'Задний правый',rear:'Сзади'}[angle]||angle}
function renderSearchResults(images){const list=$('#referenceList');if(!images.length){list.className='reference-empty';list.innerHTML='<span>⌕</span><div><strong>Ничего не найдено</strong><small>Попробуй точное название модели или выбери другой источник.</small></div>';return}list.className='reference-list';list.innerHTML=images.map((image,index)=>'<article class="reference-item source-photo" data-url="'+esc(image.imageUrl)+'" data-page="'+esc(image.pageUrl)+'"><img class="ref-thumb source-thumb" src="'+esc(image.imageUrl)+'" alt="'+esc(image.title)+'" loading="lazy"><div class="ref-meta"><strong>'+esc(image.title)+'</strong><span>'+esc(image.domain)+'</span><small>'+esc(image.engine==='yandex'?'Яндекс Картинки · открыть выдачу ↗':image.engine==='google'?'Google Images · открыть источник ↗':'Открыть исходный сайт ↗')+'</small></div><button class="ref-check" type="button" aria-label="Выбрать референс" data-select-source="'+index+'">＋</button></article>').join('');$$('.source-thumb').forEach(image=>image.addEventListener('error',()=>{image.classList.add('unavailable');image.alt='Превью недоступно у источника'}));$$('[data-select-source]').forEach(button=>button.addEventListener('click',event=>{event.stopPropagation();const row=button.closest('.source-photo');const url=row.dataset.url;const on=state.remoteReferences.includes(url);state.remoteReferences=on?state.remoteReferences.filter(item=>item!==url):[...state.remoteReferences,url].slice(0,4);row.classList.toggle('selected',!on);button.textContent=on?'＋':'✓';updateReferenceCount();toast(on?'Референс снят':'Референс добавлен к генерации')}));$$('.source-photo').forEach(row=>row.addEventListener('click',event=>{if(!event.target.closest('button'))window.open(row.dataset.page,'_blank','noopener,noreferrer')}))}
async function searchReferences(){if(state.searching)return;const model=$('#modelInput').value.trim();if(!model){toast('Введите название модели или артикул.');return}state.model=model;state.searching=true;const button=$('#searchButton');button.disabled=true;button.querySelector('span').textContent='Ищем…';$('#parserStatus').textContent='Идёт поиск';$('#referenceList').className='reference-empty';$('#referenceList').innerHTML='<span>◌</span><div><strong>Ищем реальные фото модели</strong><small>Проверяем выбранные источники.</small></div>';try{const response=await fetch('/api/search',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({model,filter:state.sourceFilter,engine:state.searchEngine})});const payload=await response.json().catch(()=>({error:'Сервис поиска вернул некорректный ответ.'}));if(!response.ok)throw new Error(payload.error||'Не удалось найти фотографии.');renderSearchResults(payload.images||[]);const labels={both:'Google + Яндекс',google:'Google',yandex:'Яндекс'};$('#parserStatus').textContent='Найдено: '+(payload.images||[]).length;$('#sourceResult').innerHTML='<span class="pulse-dot"></span><strong>Найдены реальные источники ('+labels[state.searchEngine]+'):</strong> нажми «＋» у 1–4 фото для генерации; клик по карточке открывает источник.'}catch(error){$('#parserStatus').textContent='Поиск недоступен';$('#referenceList').className='reference-empty';$('#referenceList').innerHTML='<span>!</span><div><strong>Поиск пока не подключён</strong><small>'+esc(error.message)+'</small></div>';toast(error.message)}finally{state.searching=false;button.disabled=false;button.querySelector('span').textContent='Найти референсы'}}
async function generateProject(){if(state.generating)return;const model=$('#modelInput').value.trim();const angles=selectedAngles();if(!model){toast('Сначала укажи модель техники.');return}if(angles.length<4){toast('Для пакета должны быть выбраны все 4 обязательных ракурса.');return}state.model=model;state.generating=true;const button=$('#generateButton');button.disabled=true;button.querySelector('span').textContent='Создаём кадры…';try{const local=await Promise.all(state.referenceFiles.slice(0,4).map(compactReference));const references=[...local,...state.remoteReferences].slice(0,4);for(let index=0;index<angles.length;index+=1){toast('Создаём '+angleLabel(angles[index])+' · кадр '+(index+1)+' из '+angles.length);const response=await fetch('/api/generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({model,scenario:state.scenario,angle:angles[index],referenceImages:references})});const data=await response.json();if(!response.ok)throw new Error(data.error||'Не удалось создать кадр.');if(typeof addGeneratedImage==='function')await addGeneratedImage(data)}toast('Готово: '+angles.length+' отдельных кадров.')}catch(error){toast(error.message)}finally{state.generating=false;button.disabled=false;button.querySelector('span').textContent='Сгенерировать пакет'}}
$('#clearModel').addEventListener('click',()=>{$('#modelInput').value='';$('#modelInput').focus()});$('#searchButton').addEventListener('click',searchReferences);$('#referencePhotos').addEventListener('change',event=>{state.referenceFiles=[...event.target.files].filter(file=>file.type.startsWith('image/')).slice(0,4);updateReferenceCount()});$$('.source-filter').forEach(button=>button.addEventListener('click',()=>{$$('.source-filter').forEach(item=>item.classList.remove('selected'));button.classList.add('selected');state.sourceFilter=button.dataset.sourceFilter}));$$('.search-engine').forEach(button=>button.addEventListener('click',()=>{$$('.search-engine').forEach(item=>item.classList.remove('selected'));button.classList.add('selected');state.searchEngine=button.dataset.searchEngine}));$$('.scenario-option').forEach(button=>button.addEventListener('click',()=>{$$('.scenario-option').forEach(item=>item.classList.remove('selected'));button.classList.add('selected');state.scenario=button.dataset.scenario;updateSummary()}));function setCount(next){state.count=Math.max(4,Math.min(5,next));$('#sceneCount').textContent=state.count;updateSummary()}$('#decreaseCount').addEventListener('click',()=>setCount(state.count-1));$('#increaseCount').addEventListener('click',()=>setCount(state.count+1));$$('.angle-toggle input').forEach(input=>input.addEventListener('change',()=>input.closest('.angle-toggle').classList.toggle('checked',input.checked)));$('#resetAngles').addEventListener('click',()=>{$$('.angle-toggle input').forEach(input=>{input.checked=true;input.closest('.angle-toggle').classList.add('checked')});toast('Все обязательные ракурсы восстановлены')});$$('.switch').forEach(button=>button.addEventListener('click',()=>button.classList.toggle('on')));$('#generateButton').addEventListener('click',generateProject);$('#downloadAll').addEventListener('click',()=>{if(typeof downloadAllPhotos==='function')downloadAllPhotos()});$('#copyEmbed').addEventListener('click',async()=>{const snippet='<iframe src="https://techshot-studio.vercel.app/embed/" data-profile="catalog-tech" data-output="separate-files" allow="downloads"></iframe>';try{await navigator.clipboard.writeText(snippet);toast('Код встраивания скопирован')}catch{toast('Выделите код вручную — браузер запретил доступ к буферу')}});$$('[data-scroll]').forEach(button=>button.addEventListener('click',()=>{document.getElementById(button.dataset.scroll)?.scrollIntoView({behavior:'smooth',block:'start'});$$('.nav-item').forEach(item=>item.classList.remove('active'));button.classList.add('active')}));updateSummary();updateReferenceCount();
